import{_ as d,l,o as a,c,v as o,p as i,x as r,d as s,i as n,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"overload 与强制","description":"","frontmatter":{"title":"overload 与强制","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/overload-coerce.md","filePath":"cs/overload-coerce.md","lastUpdated":1789023840000}'),h={name:"cs/overload-coerce.md"};function _(E,e,f,A,m,u){const t=l("Mermaid");return a(),c("div",null,[e[1]||(e[1]=o('<h1 id="overload-与强制" tabindex="-1">overload 与强制 <a class="header-anchor" href="#overload-与强制" aria-label="Permalink to &quot;overload 与强制&quot;">​</a></h1><div class="epigraph"><p>同一拼写可对应多套声明；隐式转换把实参送到形参类型。决议必须在翻译前选出唯一候选，否则后端看见的类型宽度没有定义。</p><footer>—— 据龙书第 6 章；C++ 标准对重载决议的分层整理</footer></div><p>上一课<a href="/cs/type-inference">类型推导直觉</a>用合一解出最一般类型，并声明重载不在合一内部。本课不重做 occurs check。缺口是<strong>多名一义</strong>与<strong>拓宽</strong>：<code>f</code> 有多条声明、<code>int</code> 可送到 <code>double</code>。要在已绑定的候选集上按类型选一，并插入转换节点。选出之后宽度已知，下一课才能发三地址。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>重载：查找返回候选集，不立即报冲突。决议：按实参类型过滤——精确匹配优于拓宽，拓宽优于经用户转换；仍多条则二义错误。运算符 <code>+</code> 是函数重载的语法糖。缺口是这份偏序，不是再综合一遍单声明表达式。</p><p>强制（coercion）：语言规定的隐式转换，如 <code>int</code> 到 <code>float</code>。必须写进规则并在 AST 上留下 <code>Cast</code> 节点，否则 IR 会用错 opcode。收窄（<code>double</code> 到 <code>int</code>）通常要求显式，以免悄悄丢精度。字符串与数值之间的「弱类型」强制不在主干。</p><h3 id="决议不是运行时分派" tabindex="-1">决议不是运行时分派 <a class="header-anchor" href="#决议不是运行时分派" aria-label="Permalink to &quot;决议不是运行时分派&quot;">​</a></h3><p>重载在编译期钉死声明。虚方法按对象动态类型跳表是另一机制，本课点名不写 vtable。不要把 <code>f(x)</code> 的重载候选留到运行时。</p><p><span class="marginnote">龙书把类型转换写成语义动作。C++ 重载决议有精确/提升/标准转换/用户定义的层次，本课只借层次直觉，不抄标准附录。Appel 强调插入转换后类型确定。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对调用：收集可见的同名函数。用实参类型（上一课已推导或检查）打分。唯一最优则绑定到那条声明，对每个实参插入必要的强制。零候选：无匹配；并列最优：二义。</p>',11)),(a(),i(p,null,{default:r(()=>[n(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20CAND%5B%22%E5%90%8C%E5%90%8D%E5%80%99%E9%80%89%22%5D%20--%3E%20RANK%5B%22%E6%8C%89%E5%8C%B9%E9%85%8D%E5%B1%82%E6%AC%A1%E6%89%93%E5%88%86%22%5D%0A%20%20RANK%20--%3E%20ONE%5B%22%E5%94%AF%E4%B8%80%E6%9C%80%E4%BD%B3%20%2B%20Cast%20%E8%8A%82%E7%82%B9%22%5D%0A%20%20RANK%20--%3E%20AMB%5B%22%E4%BA%8C%E4%B9%89%22%5D%0A%20%20RANK%20--%3E%20NONE%5B%22%E6%97%A0%E5%8C%B9%E9%85%8D%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p>可变参数、缺省实参是过滤的附加规则，点名即可。模板/泛型实例化不在本课展开。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>每个表达式节点最终一个类型、一个宽度，<a href="/cs/fixed-and-float">补码与浮点</a> 的运算种类可在 IR 选定。强制可能改变值（整数提升），副作用顺序仍按源。不要在窥孔里偷偷插转换——那是语义，不是优化。</p><p>与合一：候选选定后，若仍有类型变量，再对那一条声明合一；先选后合一，或对每条尝试合一再打分，语言定一种，本课不并行写两种实现。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不生成三地址、不分配寄存器。不处理 ADL、不写完整 C++。后课默认：能进中端的程序，调用与运算符都已钉死声明并插完 Cast。线性 IR 是下一课把树压成 \\(x\\leftarrow y\\,\\mathrm{op}\\,z\\)。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>重载在编译期按类型层次选出唯一声明。</li><li>强制显式成 AST 节点，宽度才能进 IR。</li><li>动态分派不是重载。</li><li>出处：Aho et al., 龙书第 6 章。</li></ul>',8))])}const b=d(h,[["render",_]]);export{B as __pageData,b as default};
